style.css:
@-moz-document domain("roblox.com") {
:root {
    --bg: #121212;
    --fg: #e0e0e0;
    --link: #4aa3ff;
    --accent: #ff4444;
  }

  html, body {
    background: var(--bg) !important;
    color: var(--fg) !important;
  }

  a {
    color: var(--link) !important;
  }

  button {
    background-color: var(--accent) !important;
    color: #fff !important;
  }
}
